  // The Knowledge Academy's lesson catalogue (domain/learn.ts). M246 left the module as
  // structure only — ids, categories, lengths, routes, answer indices and the keys below — so
  // every word a learner reads lives here. The categories and levels are codes the Academy
  // badge and level chip print, resolved like any other code.
  "learn.cat.analytics": "Analytics",
  "learn.cat.tactics": "Tactics",
  "learn.cat.scouting": "Scouting",
  "learn.cat.development": "Development",
  "learn.level.beginner": "Beginner",
  "learn.level.intermediate": "Intermediate",
  "learn.level.advanced": "Advanced",
  "learn.l.xg.title": "Expected Goals (xG)",
  "learn.l.xg.summary": "What xG measures and why a 0.1 chance scoring ten times is luck.",
  "learn.l.xg.p1": "Expected Goals turns a shot into a probability: a chance that, in isolation, results in a goal. A penalty sits around 0.76 xG; a tight-angle header maybe 0.05.",
  "learn.l.xg.p2": "Sum a team's shot xG and you get how many goals they 'should' have scored. When real goals exceed xG over many games, that is usually finishing quality or good fortune; when they fall short, it points to poor conversion or bad luck — not necessarily bad chances.",
  "learn.l.xg.p3": "xG is a rate, not a result. One match has enormous variance: a low-xG team can win on a deflection. Trust xG over a large sample to judge how well a side actually creates.",
  "learn.l.xg.tryIt": "See xG vs goals in the Simulation Lab",
  "learn.l.xg.q": "A team's goals are well above its cumulative xG over 30 games. The most likely reading is:",
  "learn.l.xg.o1": "They are unlucky",
  "learn.l.xg.o2": "Sustained overperformance from finishing or fortune",
  "learn.l.xg.o3": "Their xG model is broken",
  "learn.l.xg.o4": "They defend poorly",
  "learn.l.press.title": "Pressing & the defensive block",
  "learn.l.press.summary": "High press vs a low block: where you win it back and the risk trade-off.",
  "learn.l.press.p1": "Pressing is organised attempts to win the ball high up the pitch. A high press squeezes the space behind the opponent's midfield, forcing errors close to their goal — but it leaves space behind your own defensive line if it is bypassed.",
  "learn.l.press.p2": "A low block does the opposite: it protects space behind the defence, invites pressure and hits on the counter, but concedes territory and lets opponents build from deep.",
  "learn.l.press.p3": "The 'height' of your press and your defensive line are two of the most consequential dials a manager sets; the Football OS engine models both as a press intensity and a mentality that shifts your line up or down.",
  "learn.l.press.tryIt": "Set a press and watch the match change",
  "learn.l.press.q": "The main risk of a sustained high press is:",
  "learn.l.press.o1": "Too few chances",
  "learn.l.press.o2": "Space behind your defensive line when the press is beaten",
  "learn.l.press.o3": "Lower possession",
  "learn.l.press.o4": "More substitutions",
  "learn.l.formations.title": "Formations vs roles",
  "learn.l.formations.summary": "Why 4-3-3 in name can be a 2-3-5 in attack.",
  "learn.l.formations.p1": "A formation is a starting snapshot of positions. What matters is the structure in possession: full-backs tucking in turn a 4-3-3 into a 2-3-5; a single pivot sits as a 3-2-5 build.",
  "learn.l.formations.p2": "Roles describe behaviour — an inside forward drifts centrally, a box-to-box mid covers both boxes, an inverted full-back moves infield. Two teams can share a number and look completely different.",
  "learn.l.formations.p3": "When you build a shape, think in phases: how you defend, how you build from the back, and how you attack. Dragging tokens in the Tactical Studio is exactly this exercise.",
  "learn.l.formations.tryIt": "Build a shape",
  "learn.l.formations.q": "The best way to describe how a team really plays is:",
  "learn.l.formations.o1": "Its formation number only",
  "learn.l.formations.o2": "Its roles and behaviour across phases of play",
  "learn.l.formations.o3": "Its average player height",
  "learn.l.formations.o4": "Its possession percentage",
  "learn.l.value.title": "Market value vs ability",
  "learn.l.value.summary": "Age, potential and contract length move price as much as current quality.",
  "learn.l.value.p1": "Market value is not a pure function of ability. A 22-year-old with high potential can out-price a better 31-year-old, because resale value and years of prime remain.",
  "learn.l.value.p2": "Contract length is a lever too: a player entering the final year can be cheap to buy and expensive to keep, since the selling club loses leverage.",
  "learn.l.value.p3": "Good scouting separates present contribution from future trajectory. In Football OS the player cards show overall, potential, age and value together precisely so you can reason about the gap between them.",
  "learn.l.value.tryIt": "Weigh asking fee against headroom on the Transfer Board",
  "learn.l.value.q": "All else equal, which raises a player's market value the most?",
  "learn.l.value.o1": "Older age",
  "learn.l.value.o2": "Shorter remaining contract",
  "learn.l.value.o3": "High potential and young age",
  "learn.l.value.o4": "Playing in a lower league",
  "learn.l.sample.title": "Sample size & variance",
  "learn.l.sample.summary": "Why you cannot judge a striker in six games.",
  "learn.l.sample.p1": "Football is a low-scoring, high-variance sport. Small samples are dominated by luck: streaky finishing, deflections, refereeing decisions.",
  "learn.l.sample.p2": "Underlying indicators that aggregate many events — shot volume, xG, chances conceded — stabilise far sooner than goals or points do. Use them to form an early view, then let results confirm or deny it.",
  "learn.l.sample.p3": "This is why a season simulation, not one match, is the honest way to judge whether a squad or tactic works.",
  "learn.l.sample.tryIt": "Run a full season",
  "learn.l.sample.q": "Which metric stabilises fastest as a signal of true quality?",
  "learn.l.sample.o1": "Goals scored in the last 3 games",
  "learn.l.sample.o2": "League position after a week",
  "learn.l.sample.o3": "Shot xG per match over many games",
  "learn.l.sample.o4": "A single hat-trick",
  "learn.l.load.title": "Training load & recovery",
  "learn.l.load.summary": "Progress needs the right dose of stress and rest, not maximal effort.",
