  "learn.l.xg.summary": "xG 衡量的是什麼，以及為什麼 0.1 的機會進十次只是運氣。",
  "learn.l.xg.p1": "預期進球把一次射門變成一個機率：這次機會單獨來看有多大機率進球。十二碼大約 0.76 xG，小角度頭槌可能只有 0.05。",
  "learn.l.xg.p2": "把一支球隊所有射門的 xG 加起來，就是他們「本來該」打進的球數。如果很多場比賽下來實際進球持續高於 xG，通常代表終結品質高或運氣好；如果低於 xG，則指向轉化效率差或運氣差——而不一定是機會不好。",
  "learn.l.xg.p3": "xG 是速率，不是結果。單場比賽的變異極大：xG 很低的一方也可能靠一次折射贏球。要判斷一支球隊的創造力，請在大樣本上看 xG。",
